	let finalSummary = parsed.suggestedSummary || "";
	if (language === "en") {
		const sLower = (finalSummary || "").toLowerCase();
		if (!finalSummary || sLower.includes("líder comercial") || sLower.includes("desarrollador") || sLower.includes("artista técnico") || sLower.includes("con un perfil integral")) finalSummary = "Lead Automation Engineer and Platform Developer combining full-stack web and sensor telemetry with modern AI API integrations and 3D simulation engineering. Currently Lead Automation Engineer & Platform Developer at Orblite, engineering AI workflow automations, vehicle telematics infrastructure, and custom internal ERP/CRM applications (TypeScript, React, RESTful APIs, SQL Supabase, AI/LLM APIs, Cloudflare). Extensive background developing industrial Digital Twins for global Fortune 500 enterprise clients (automotive, tech, and pharmaceutical sectors under strict NDAs) and Technical Art for premier AAA sports franchise at an elite co-development studio (verified shipped credit on MobyGames for EA Sports College Football 25, interactive UI/UX in Frostbite, Perforce P4, and Jenkins CI).";
	} else if (!finalSummary) finalSummary = resume.personalInfo.summary;
