	spawnFloatingText(pos, text, colorHex) {
		const canvas = document.createElement("canvas");
		canvas.width = 512;
		canvas.height = 128;
		const ctx = canvas.getContext("2d");
		if (!ctx) return;
		ctx.font = "900 42px \"Inter\", \"Segoe UI\", sans-serif";
		ctx.textAlign = "center";
		ctx.textBaseline = "middle";
		ctx.shadowColor = "rgba(0, 0, 0, 0.85)";
		ctx.shadowBlur = 10;
		ctx.shadowOffsetX = 3;
		ctx.shadowOffsetY = 3;
		ctx.strokeStyle = "#020617";
		ctx.lineWidth = 8;
		ctx.strokeText(text, 256, 64);
		ctx.fillStyle = "#" + colorHex.toString(16).padStart(6, "0");
		ctx.fillText(text, 256, 64);
		const texture = new CanvasTexture(canvas);
		texture.colorSpace = SRGBColorSpace;
		const material = new SpriteMaterial({
			map: texture,
			transparent: true,
			depthTest: false,
			depthWrite: false
		});
		const sprite = new Sprite(material);
		sprite.position.set(pos.x, pos.y + .65, pos.z);
		sprite.scale.set(1.5, .38, 1);
		this.vfxGroup.add(sprite);
		const startTime = performance.now();
		const duration = 950;
		const startY = sprite.position.y;
		const animateSprite = () => {
			const elapsed = performance.now() - startTime;
			const progress = Math.min(1, elapsed / duration);
			sprite.position.y = startY + progress * .7;
			sprite.scale.set(1.5 * (1 + progress * .2), .38 * (1 + progress * .2), 1);
			material.opacity = Math.max(0, 1 - Math.pow(progress, 1.8));
			if (progress < 1) requestAnimationFrame(animateSprite);
			else {
				this.vfxGroup.remove(sprite);
				texture.dispose();
				material.dispose();
			}
		};
		requestAnimationFrame(animateSprite);
	}
