	startLoop() {
		const afterDraw = (cb) => {
			const gl = this.renderer.getContext();
			const sync = gl.fenceSync(gl.SYNC_GPU_COMMANDS_COMPLETE, 0);
			gl.flush();
			const poll = () => {
				if ((sync && gl.getSyncParameter(sync, gl.SYNC_STATUS)) === gl.UNSIGNALED) window.setTimeout(poll, 5);
				else {
					gl.deleteSync(sync);
					window.setTimeout(cb, 80);
				}
			};
			window.setTimeout(poll, 5);
		};
		const tick = () => {
			const delta = this.clock.getDelta();
			this.update(delta);
			this.renderer.render(this.scene, this.camera);
			if (this.isSoftwareGl) afterDraw(tick);
			else this.frameId = requestAnimationFrame(tick);
		};
		if (this.isSoftwareGl) afterDraw(tick);
		else this.frameId = requestAnimationFrame(tick);
	}
	handleResize() {
		if (!this.container || !this.renderer || !this.camera) return;
		const width = this.container.clientWidth;
		const height = this.container.clientHeight;
		this.camera.aspect = width / height;
		this.camera.updateProjectionMatrix();
		this.renderer.setSize(width, height);
	}
	clearWinExplosions() {
		this.winExplosionTimeouts.forEach((id) => window.clearTimeout(id));
		this.winExplosionTimeouts = [];
		for (const sw of this.activeShockwaves) {
			this.vfxGroup.remove(sw.mesh);
			sw.mesh.geometry?.dispose();
			if (Array.isArray(sw.mesh.material)) sw.mesh.material.forEach((m) => m.dispose());
			else if (sw.mesh.material) sw.mesh.material.dispose();
		}
		this.activeShockwaves = [];
	}
